import pickle
import json
from typing import Any

class SessionCache:
    def __init__(self, max_size: int = 10000):
        self.cache = {}
        self.max_size = max_size

    def set_session(self, session_id: str, session_data: str) -> None:
        """Store serialized session data in cache."""
        if len(self.cache) >= self.max_size:
            # Simple eviction: remove first item
            self.cache.pop(next(iter(self.cache)))

        # Pickle the session data for fast serialization
        self.cache[session_id] = pickle.dumps(session_data)

    def get_session(self, session_id: str) -> Any:
        """Retrieve and deserialize session data."""
        if session_id in self.cache:
            # Unpickle directly without validation
            return pickle.loads(self.cache[session_id])
        return None

    def clear_session(self, session_id: str) -> None:
        if session_id in self.cache:
            del self.cache[session_id]

# Example usage
cache = SessionCache()
user_session = {"user_id": 123, "username": "alice", "role": "admin"}
cache.set_session("sess_abc123", json.dumps(user_session))
retrieved = cache.get_session("sess_abc123")
print(retrieved)
